/**
 * Hideout Module – interactive pick bonus (reusable pick-game engine).
 *
 * The 12-chest board is generated by the authoritative engine when the feature
 * starts and stored server-side; the client only learns a chest's content when
 * it is opened. Collected prizes can never be lost.
 */
import type { GameConfig } from '../../config/gameConfig';
import { pickWeightedList, type Rng } from '../rng';

export type ChestPrize =
  | { type: 'coins'; value: number } // × total bet
  | { type: 'multiplier'; value: number } // +value to bonus multiplier
  | { type: 'extraPick' }
  | { type: 'treasure'; value: number } // Lampião's treasure, × total bet
  | { type: 'medallion' } // Maria's medallion – doubles the multiplier
  | { type: 'empty' };

export interface HideoutState {
  board: ChestPrize[]; // HIDDEN – never sent to the client before opening
  opened: (number | null)[]; // pick order index per chest, null when closed
  picksLeft: number;
  picksUsed: number;
  coinTotal: number; // × total bet (coins + treasure + couple)
  multiplier: number;
  hasTreasure: boolean;
  hasMedallion: boolean;
  couplesFortune: boolean;
  ended: boolean;
}

export interface PickResult {
  index: number;
  prize: ChestPrize;
  couplesFortune: boolean; // unlocked by this pick
  picksLeft: number;
  coinTotal: number;
  multiplier: number;
  /** Running award (cents) = coinTotal × multiplier × bet (capped). */
  award: number;
  ended: boolean;
  /** Full board reveal, only present when the feature has ended. */
  reveal?: ChestPrize[];
}

export type HideoutCfg = GameConfig['hideout'];

export function generateBoard(rng: Rng, cfg: HideoutCfg): ChestPrize[] {
  const board: ChestPrize[] = [];
  const used: Record<string, number> = {};
  for (let i = 0; i < cfg.chests; i++) {
    const allowed = cfg.prizes.filter((p) => !('max' in p) || (used[p.type] || 0) < (p as { max: number }).max);
    const def = pickWeightedList(rng, allowed.map((p) => ({ v: p, w: p.weight })));
    used[def.type] = (used[def.type] || 0) + 1;
    switch (def.type) {
      case 'coins':
        board.push({ type: 'coins', value: pickWeightedList(rng, (def as unknown as { values: { v: number; w: number }[] }).values) });
        break;
      case 'multiplier':
        board.push({ type: 'multiplier', value: pickWeightedList(rng, (def as unknown as { values: { v: number; w: number }[] }).values) });
        break;
      case 'treasure':
        board.push({ type: 'treasure', value: (def as { value: number }).value });
        break;
      case 'extraPick':
      case 'medallion':
      case 'empty':
        board.push({ type: def.type } as ChestPrize);
        break;
    }
  }
  return board;
}

export function startHideout(rng: Rng, cfg: HideoutCfg): HideoutState {
  return {
    board: generateBoard(rng, cfg),
    opened: Array(cfg.chests).fill(null),
    picksLeft: cfg.initialPicks,
    picksUsed: 0,
    coinTotal: 0,
    multiplier: cfg.multiplierStart,
    hasTreasure: false,
    hasMedallion: false,
    couplesFortune: false,
    ended: false,
  };
}

export function hideoutAward(state: Pick<HideoutState, 'coinTotal' | 'multiplier'>, totalBet: number, cap: number): number {
  return Math.min(cap, state.coinTotal * state.multiplier * totalBet);
}

export function pickChest(state: HideoutState, index: number, cfg: HideoutCfg, totalBet: number, cap: number): { state: HideoutState; result: PickResult } {
  if (state.ended) throw new Error('Hideout has ended');
  if (!Number.isInteger(index) || index < 0 || index >= state.board.length) throw new Error('Invalid chest');
  if (state.opened[index] !== null) throw new Error('Chest already opened');
  if (state.picksLeft <= 0) throw new Error('No picks left');

  const s: HideoutState = { ...state, opened: state.opened.slice() };
  const prize = s.board[index];
  s.opened[index] = s.picksUsed;
  s.picksUsed++;
  s.picksLeft--;

  let couple = false;
  switch (prize.type) {
    case 'coins':
      s.coinTotal += prize.value;
      break;
    case 'treasure':
      s.coinTotal += prize.value;
      s.hasTreasure = true;
      break;
    case 'multiplier':
      s.multiplier += prize.value;
      break;
    case 'medallion':
      s.multiplier *= 2;
      s.hasMedallion = true;
      break;
    case 'extraPick':
      if (s.picksUsed + s.picksLeft < cfg.maxPicks) s.picksLeft++;
      break;
    case 'empty':
      break;
  }
  if (s.hasTreasure && s.hasMedallion && !s.couplesFortune) {
    s.couplesFortune = true;
    s.coinTotal += cfg.couplesFortune;
    couple = true;
  }
  const award = hideoutAward(s, totalBet, cap);
  const unopened = s.opened.some((o) => o === null);
  s.ended = s.picksLeft <= 0 || !unopened || award >= cap;
  return {
    state: s,
    result: {
      index,
      prize,
      couplesFortune: couple,
      picksLeft: s.picksLeft,
      coinTotal: s.coinTotal,
      multiplier: s.multiplier,
      award,
      ended: s.ended,
      reveal: s.ended ? s.board.slice() : undefined,
    },
  };
}

/** Client-safe view of the hideout (hides unopened chests). */
export function publicHideout(s: HideoutState) {
  return {
    chests: s.board.map((p, i) => (s.opened[i] !== null || s.ended ? { opened: s.opened[i] !== null, prize: p } : { opened: false, prize: null })),
    picksLeft: s.picksLeft,
    picksUsed: s.picksUsed,
    coinTotal: s.coinTotal,
    multiplier: s.multiplier,
    hasTreasure: s.hasTreasure,
    hasMedallion: s.hasMedallion,
    couplesFortune: s.couplesFortune,
    ended: s.ended,
  };
}
export type PublicHideout = ReturnType<typeof publicHideout>;
